Here is a Python implementation of the Template Method pattern for sorting:

```python
from abc import ABC, abstractmethod
from typing import List, Any

class SortAlgorithm(ABC):
    def __init__(self, data: List[Any]):
        self.data = data.copy()

    # Template Method
    def sort(self) -> List[Any]:
        n = len(self.data)
        self._sort_impl(n)
        return self.data

    @abstractmethod
    def _sort_impl(self, n: int) -> None:
        """Algorithm specific skeleton. Must use compare() and swap()"""
        pass

    def compare(self, i: int, j: int) -> int:
        a, b = self.data[i], self.data[j]
        if a < b:
            return -1
        if a > b:
            return 1
        return 0

    def swap(self, i: int, j: int) -> None:
        self.data[i], self.data[j] = self.data[j], self.data[i]


class BubbleSort(SortAlgorithm):
    def _sort_impl(self, n: int) -> None:
        for i in range(n):
            swapped = False
            for j in range(0, n - i - 1):
                if self.compare(j, j + 1) > 0:
                    self.swap(j, j + 1)
                    swapped = True
            if not swapped:
                break


class SelectionSort(SortAlgorithm):
    def _sort_impl(self, n: int) -> None:
        for i in range(n):
            min_idx = i
            for j in range(i + 1, n):
                if self.compare(j, min_idx) < 0:
                    min_idx = j
            if min_idx != i:
                self.swap(i, min_idx)


# Test
if __name__ == "__main__":
    nums = [64, 25, 12, 22, 11]
    strs = ["delta", "alpha", "charlie", "bravo"]

    for algo_cls in [BubbleSort, SelectionSort]:
        nums_copy = nums.copy()
        sorted_nums = algo_cls(nums_copy).sort()
        print(f"{algo_cls.__name__} ints: {sorted_nums}")

        strs_copy = strs.copy()
        sorted_strs = algo_cls(strs_copy).sort()
        print(f"{algo_cls.__name__} strs: {sorted_strs}")
        print()
```

The abstract `SortAlgorithm` defines the template method `sort` and provides the primitive operations `compare` and `swap`. `BubbleSort` and `SelectionSort` implement their own `_sort_impl` using those primitives, keeping the overall sorting skeleton in the base class.
